//github.com/crystal-lang/crystal/blob/af0f55415/src/xml/save_options.cr#L16"},"def":{"name":"xhtml?","visibility":"Public","body":"self.includes?(XHTML)"},"external_var":false}]},{"html_id":"Crystal/XML/XPathContext","path":"XML/XPathContext.html","kind":"class","full_name":"XML::XPathContext","name":"XPathContext","abstract":false,"superclass":{"html_id":"Crystal/Reference","kind":"class","full_name":"Reference","name":"Reference"},"ancestors":[{"html_id":"Crystal/Reference","kind":"class","full_name":"Reference","name":"Reference"},{"html_id":"Crystal/Object","kind":"class","full_name":"Object","name":"Object"}],"locations":[{"filename":"src/xml/xpath_context.cr","line_number":1,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L1"}],"repository_name":"Crystal","program":false,"enum":false,"alias":false,"const":false,"namespace":{"html_id":"Crystal/XML","kind":"module","full_name":"XML","name":"XML"},"constructors":[{"html_id":"new(node:Node)-class-method","name":"new","abstract":false,"args":[{"name":"node","external_name":"node","restriction":"Node"}],"args_string":"(node : Node)","args_html":"(node : <a href=\"../XML/Node.html\">Node</a>)","location":{"filename":"src/xml/xpath_context.cr","line_number":4,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L4"},"def":{"name":"new","args":[{"name":"node","external_name":"node","restriction":"Node"}],"visibility":"Public","body":"_ = allocate\n_.initialize(node)\nif _.responds_to?(:finalize)\n  ::GC.add_finalizer(_)\nend\n_\n"},"external_var":false}],"instance_methods":[{"html_id":"errors:Array(XML::Error)-instance-method","name":"errors","abstract":false,"location":{"filename":"src/xml/xpath_context.cr","line_number":2,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L2"},"def":{"name":"errors","visibility":"Public","body":"@errors"},"external_var":false},{"html_id":"evaluate(search_path:String)-instance-method","name":"evaluate","abstract":false,"args":[{"name":"search_path","external_name":"search_path","restriction":"String"}],"args_string":"(search_path : String)","args_html":"(search_path : <a href=\"../String.html\">String</a>)","location":{"filename":"src/xml/xpath_context.cr","line_number":9,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L9"},"def":{"name":"evaluate","args":[{"name":"search_path","external_name":"search_path","restriction":"String"}],"visibility":"Public","body":"xpath = XML::Error.collect_generic(@errors) do LibXML.xmlXPathEvalExpression(search_path, self) end\n\nif xpath\nelse\n  raise(XML::Error.new(\"Error in '#{search_path}' expression\", 0))\nend\n\ncase xpath.value.type\nwhen LibXML::XPathObjectType::STRING\n  String.new(xpath.value.stringval)\nwhen LibXML::XPathObjectType::NUMBER\n  xpath.value.floatval\nwhen LibXML::XPathObjectType::BOOLEAN\n  xpath.value.boolval != 0\nwhen LibXML::XPathObjectType::NODESET\n  if xpath.value.nodesetval\n    NodeSet.new(Node.new(@ctx.value.doc), xpath.value.nodesetval)\n  else\n    NodeSet.new(Node.new(@ctx.value.doc))\n  end\nelse\n  NodeSet.new(Node.new(@ctx.value.doc))\nend\n"},"external_var":false},{"html_id":"register_namespace(prefix:String,uri:String|Nil)-instance-method","name":"register_namespace","abstract":false,"args":[{"name":"prefix","external_name":"prefix","restriction":"String"},{"name":"uri","external_name":"uri","restriction":"String | ::Nil"}],"args_string":"(prefix : String, uri : String | Nil)","args_html":"(prefix : <a href=\"../String.html\">String</a>, uri : <a href=\"../String.html\">String</a> | <a href=\"../Nil.html\">Nil</a>)","location":{"filename":"src/xml/xpath_context.cr","line_number":38,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L38"},"def":{"name":"register_namespace","args":[{"name":"prefix","external_name":"prefix","restriction":"String"},{"name":"uri","external_name":"uri","restriction":"String | ::Nil"}],"visibility":"Public","body":"prefix = prefix.lchop(\"xmlns:\")\nLibXML.xmlXPathRegisterNs(self, prefix, uri.to_s)\n"},"external_var":false},{"html_id":"register_namespaces(namespaces):Nil-instance-method","name":"register_namespaces","abstract":false,"args":[{"name":"namespaces","external_name":"namespaces","restriction":""}],"args_string":"(namespaces) : Nil","args_html":"(namespaces) : <a href=\"../Nil.html\">Nil</a>","location":{"filename":"src/xml/xpath_context.cr","line_number":32,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L32"},"def":{"name":"register_namespaces","args":[{"name":"namespaces","external_name":"namespaces","restriction":""}],"return_type":"Nil","visibility":"Public","body":"namespaces.each do |prefix, uri|\n  register_namespace(prefix, uri)\nend"},"external_var":false},{"html_id":"register_variable(name,value)-instance-method","name":"register_variable","abstract":false,"args":[{"name":"name","external_name":"name","restriction":""},{"name":"value","external_name":"value","restriction":""}],"args_string":"(name, value)","args_html":"(name, value)","location":{"filename":"src/xml/xpath_context.cr","line_number":49,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L49"},"def":{"name":"register_variable","args":[{"name":"name","external_name":"name","restriction":""},{"name":"value","external_name":"value","restriction":""}],"visibility":"Public","body":"case value\nwhen Bool\n  obj = LibXML.xmlXPathNewBoolean(value ? 1 : 0)\nwhen Number\n  obj = LibXML.xmlXPathNewFloat(value.to_f64)\nelse\n  obj = LibXML.xmlXPathNewCString(value.to_s)\nend\nLibXML.xmlXPathRegisterVariable(self, name, obj)\n"},"external_var":false},{"html_id":"register_variables(variables):Nil-instance-method","name":"register_variables","abstract":false,"args":[{"name":"variables","external_name":"variables","restriction":""}],"args_string":"(variables) : Nil","args_html":"(variables) : <a href=\"../Nil.html\">Nil</a>","location":{"filename":"src/xml/xpath_context.cr","line_number":43,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L43"},"def":{"name":"register_variables","args":[{"name":"variables","external_name":"variables","restriction":""}],"return_type":"Nil","visibility":"Public","body":"variables.each do |name, value|\n  register_variable(name, value)\nend"},"external_var":false},{"html_id":"to_unsafe:Pointer(LibXML::XPathContext)-instance-method","name":"to_unsafe","abstract":false,"location":{"filename":"src/xml/xpath_context.cr","line_number":62,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/xml/xpath_context.cr#L62"},"def":{"name":"to_unsafe","visibility":"Public","body":"@ctx"},"external_var":false}]}]},{"html_id":"Crystal/YAML","path":"YAML.html","kind":"module","full_name":"YAML","name":"YAML","abstract":false,"locations":[{"filename":"src/yaml.cr","line_number":79,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L79"},{"filename":"src/yaml/any.cr","line_number":27,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L27"},{"filename":"src/yaml/builder.cr","line_number":225,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/builder.cr#L225"},{"filename":"src/yaml/enums.cr","line_number":1,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/enums.cr#L1"},{"filename":"src/yaml/serialization.cr","line_number":1,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/serialization.cr#L1"}],"repository_name":"Crystal","program":false,"enum":false,"alias":false,"const":false,"doc":"The YAML module provides serialization and deserialization of YAML\nversion 1.1 to/from native Crystal data structures, with the additional\nindependent types specified in http://yaml.org/type/\n\nNOTE: To use `YAML`, you must explicitly import it with `require \"yaml\"`\n\n### Parsing with `#parse` and `#parse_all`\n\n`YAML.parse` will return an `Any`, which is a convenient wrapper around all possible\nYAML core types, making it easy to traverse a complex YAML structure but requires\nsome casts from time to time, mostly via some method invocations.\n\n```\nrequire \"yaml\"\n\ndata = YAML.parse <<-YAML\n         ---\n         foo:\n           bar:\n             baz:\n               - qux\n               - fox\n         YAML\ndata[\"foo\"][\"bar\"][\"baz\"][1].as_s # => \"fox\"\n```\n\n`YAML.parse` can read from an `IO` directly (such as a file) which saves\nallocating a string:\n\n```\nrequire \"yaml\"\n\nyaml = File.open(\"path/to/file.yml\") do |file|\n  YAML.parse(file)\nend\n```\n\n### Parsing with `from_yaml`\n\nA type `T` can be deserialized from YAML by invoking `T.from_yaml(string_or_io)`.\nFor this to work, `T` must implement\n`new(ctx : YAML::PullParser, node : YAML::Nodes::Node)` and decode\na value from the given *node*, using *ctx* to store and retrieve\nanchored values (see `YAML::PullParser` for an explanation of this).\n\nCrystal primitive types, `Time`, `Bytes` and `Union` implement\nthis method. `YAML::Serializable` can be used to implement this method\nfor user types.\n\n### Dumping with `YAML.dump` or `#to_yaml`\n\n`YAML.dump` generates the YAML representation for an object.\nAn `IO` can be passed and it will be written there,\notherwise it will be returned as a string. Similarly, `#to_yaml`\n(with or without an `IO`) on any object does the same.\n\nFor this to work, the type given to `YAML.dump` must implement\n`to_yaml(builder : YAML::Nodes::Builder`).\n\nCrystal primitive types, `Time` and `Bytes` implement\nthis method. `YAML::Serializable` can be used to implement this method\nfor user types.\n\n```\nyaml = YAML.dump({hello: \"world\"})                               # => \"---\\nhello: world\\n\"\nFile.open(\"foo.yml\", \"w\") { |f| YAML.dump({hello: \"world\"}, f) } # writes it to the file\n# or:\nyaml = {hello: \"world\"}.to_yaml                               # => \"---\\nhello: world\\n\"\nFile.open(\"foo.yml\", \"w\") { |f| {hello: \"world\"}.to_yaml(f) } # writes it to the file\n```","summary":"<p>The YAML module provides serialization and deserialization of YAML version 1.1 to/from native Crystal data structures, with the additional independent types specified in http://yaml.org/type/</p>","class_methods":[{"html_id":"build(io:IO,&):Nil-class-method","name":"build","doc":"Writes YAML into the given `IO`. A `YAML::Builder` is yielded to the block.","summary":"<p>Writes YAML into the given <code><a href=\"IO.html\">IO</a></code>.</p>","abstract":false,"args":[{"name":"io","external_name":"io","restriction":"IO"}],"args_string":"(io : IO, &) : Nil","args_html":"(io : <a href=\"IO.html\">IO</a>, &) : <a href=\"Nil.html\">Nil</a>","location":{"filename":"src/yaml/builder.cr","line_number":251,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/builder.cr#L251"},"def":{"name":"build","args":[{"name":"io","external_name":"io","restriction":"IO"}],"yields":1,"block_arity":1,"return_type":"Nil","visibility":"Public","body":"YAML::Builder.build(io) do |yaml|\n  yaml.stream do\n    yaml.document do\n      yield yaml\n    end\n  end\nend"},"external_var":false},{"html_id":"build(&)-class-method","name":"build","doc":"Returns the resulting String of writing YAML to the yielded `YAML::Builder`.\n\n```\nrequire \"yaml\"\n\nstring = YAML.build do |yaml|\n  yaml.mapping do\n    yaml.scalar \"foo\"\n    yaml.sequence do\n      yaml.scalar 1\n      yaml.scalar 2\n    end\n  end\nend\nstring # => \"---\\nfoo:\\n- 1\\n- 2\\n\"\n```","summary":"<p>Returns the resulting String of writing YAML to the yielded <code><a href=\"YAML/Builder.html\">YAML::Builder</a></code>.</p>","abstract":false,"location":{"filename":"src/yaml/builder.cr","line_number":242,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/builder.cr#L242"},"def":{"name":"build","yields":1,"block_arity":1,"visibility":"Public","body":"String.build do |str|\n  build(str) do |yaml|\n    yield yaml\n  end\nend"},"external_var":false},{"html_id":"dump(object,io:IO):Nil-class-method","name":"dump","doc":"Serializes an object to YAML, writing it to *io*.","summary":"<p>Serializes an object to YAML, writing it to <em>io</em>.</p>","abstract":false,"args":[{"name":"object","external_name":"object","restriction":""},{"name":"io","external_name":"io","restriction":"IO"}],"args_string":"(object, io : IO) : Nil","args_html":"(object, io : <a href=\"IO.html\">IO</a>) : <a href=\"Nil.html\">Nil</a>","location":{"filename":"src/yaml.cr","line_number":160,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L160"},"def":{"name":"dump","args":[{"name":"object","external_name":"object","restriction":""},{"name":"io","external_name":"io","restriction":"IO"}],"return_type":"Nil","visibility":"Public","body":"object.to_yaml(io)"},"external_var":false},{"html_id":"dump(object):String-class-method","name":"dump","doc":"Serializes an object to YAML, returning it as a `String`.","summary":"<p>Serializes an object to YAML, returning it as a <code><a href=\"String.html\">String</a></code>.</p>","abstract":false,"args":[{"name":"object","external_name":"object","restriction":""}],"args_string":"(object) : String","args_html":"(object) : <a href=\"String.html\">String</a>","location":{"filename":"src/yaml.cr","line_number":155,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L155"},"def":{"name":"dump","args":[{"name":"object","external_name":"object","restriction":""}],"return_type":"String","visibility":"Public","body":"object.to_yaml"},"external_var":false},{"html_id":"libyaml_version:SemanticVersion-class-method","name":"libyaml_version","doc":"Returns the used version of `libyaml`.","summary":"<p>Returns the used version of <code>libyaml</code>.</p>","abstract":false,"location":{"filename":"src/yaml.cr","line_number":165,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L165"},"def":{"name":"libyaml_version","return_type":"SemanticVersion","visibility":"Public","body":"LibYAML.yaml_get_version(out major, out minor, out patch)\n\nSemanticVersion.new(major, minor, patch)\n"},"external_var":false},{"html_id":"parse(data:String|IO):Any-class-method","name":"parse","doc":"Deserializes a YAML document according to the core schema.\n\n```yaml\n# ./foo.yml\ndata:\n  string: \"foobar\"\n  array:\n    - John\n    - Sarah\n  hash: {key: value}\n  paragraph: |\n    foo\n    bar\n```\n\n```\nrequire \"yaml\"\n\nYAML.parse(File.read(\"./foo.yml\"))\n# => {\n# => \"data\" => {\n# => \"string\" => \"foobar\",\n# => \"array\" => [\"John\", \"Sarah\"],\n# => \"hash\" => {\"key\" => \"value\"},\n# => \"paragraph\" => \"foo\\nbar\\n\"\n# => }\n```","summary":"<p>Deserializes a YAML document according to the core schema.</p>","abstract":false,"args":[{"name":"data","external_name":"data","restriction":"String | IO"}],"args_string":"(data : String | IO) : Any","args_html":"(data : <a href=\"String.html\">String</a> | <a href=\"IO.html\">IO</a>) : <a href=\"YAML/Any.html\">Any</a>","location":{"filename":"src/yaml.cr","line_number":131,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L131"},"def":{"name":"parse","args":[{"name":"data","external_name":"data","restriction":"String | IO"}],"return_type":"Any","visibility":"Public","body":"YAML::Schema::Core.parse(data)"},"external_var":false},{"html_id":"parse_all(data:String):Array(Any)-class-method","name":"parse_all","doc":"Deserializes multiple YAML documents according to the core schema.\n\n```yaml\n# ./foo.yml\nfoo: bar\n---\nhello: world\n```\n\n```\nrequire \"yaml\"\n\nYAML.parse_all(File.read(\"./foo.yml\"))\n# => [{\"foo\" => \"bar\"}, {\"hello\" => \"world\"}]\n```","summary":"<p>Deserializes multiple YAML documents according to the core schema.</p>","abstract":false,"args":[{"name":"data","external_name":"data","restriction":"String"}],"args_string":"(data : String) : Array(Any)","args_html":"(data : <a href=\"String.html\">String</a>) : <a href=\"Array.html\">Array</a>(<a href=\"YAML/Any.html\">Any</a>)","location":{"filename":"src/yaml.cr","line_number":150,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml.cr#L150"},"def":{"name":"parse_all","args":[{"name":"data","external_name":"data","restriction":"String"}],"return_type":"Array(Any)","visibility":"Public","body":"YAML::Schema::Core.parse_all(data)"},"external_var":false}],"types":[{"html_id":"Crystal/YAML/Any","path":"YAML/Any.html","kind":"struct","full_name":"YAML::Any","name":"Any","abstract":false,"superclass":{"html_id":"Crystal/Struct","kind":"struct","full_name":"Struct","name":"Struct"},"ancestors":[{"html_id":"Crystal/Struct","kind":"struct","full_name":"Struct","name":"Struct"},{"html_id":"Crystal/Value","kind":"struct","full_name":"Value","name":"Value"},{"html_id":"Crystal/Object","kind":"class","full_name":"Object","name":"Object"}],"locations":[{"filename":"src/yaml/any.cr","line_number":27,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L27"}],"repository_name":"Crystal","program":false,"enum":false,"alias":false,"const":false,"namespace":{"html_id":"Crystal/YAML","kind":"module","full_name":"YAML","name":"YAML"},"doc":"`YAML::Any` is a convenient wrapper around all possible YAML core types\n(`YAML::Any::Type`) and can be used for traversing dynamic or\nunknown YAML structures.\n\n```\nrequire \"yaml\"\n\ndata = YAML.parse <<-YAML\n         ---\n         foo:\n           bar:\n             baz:\n               - qux\n               - fox\n         YAML\ndata[\"foo\"][\"bar\"][\"baz\"][0].as_s # => \"qux\"\ndata[\"foo\"][\"bar\"][\"baz\"].as_a    # => [\"qux\", \"fox\"]\n```\n\nNote that methods used to traverse a YAML structure, `#[]`, `#[]?` and `#each`,\nalways return a `YAML::Any` to allow further traversal. To convert them to `String`,\n`Array`, etc., use the `as_` methods, such as `#as_s`, `#as_a`, which perform\na type check against the raw underlying value. This means that invoking `#as_s`\nwhen the underlying value is not a `String` will raise: the value won't automatically\nbe converted (parsed) to a `String`. There are also nil-able variants (`#as_i?`, `#as_s?`, ...),\nwhich return `nil` when the underlying value type won't match.","summary":"<p><code><a href=\"../YAML/Any.html\">YAML::Any</a></code> is a convenient wrapper around all possible YAML core types (<code><a href=\"../YAML/Any/Type.html\">YAML::Any::Type</a></code>) and can be used for traversing dynamic or unknown YAML structures.</p>","constructors":[{"html_id":"new(ctx:YAML::ParseContext,node:YAML::Nodes::Node)-class-method","name":"new","abstract":false,"args":[{"name":"ctx","external_name":"ctx","restriction":"YAML::ParseContext"},{"name":"node","external_name":"node","restriction":"YAML::Nodes::Node"}],"args_string":"(ctx : YAML::ParseContext, node : YAML::Nodes::Node)","args_html":"(ctx : <a href=\"../YAML/ParseContext.html\">YAML::ParseContext</a>, node : <a href=\"../YAML/Nodes/Node.html\">YAML::Nodes::Node</a>)","location":{"filename":"src/yaml/any.cr","line_number":31,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L31"},"def":{"name":"new","args":[{"name":"ctx","external_name":"ctx","restriction":"YAML::ParseContext"},{"name":"node","external_name":"node","restriction":"YAML::Nodes::Node"}],"visibility":"Public","body":"case node\nwhen YAML::Nodes::Scalar\n  new(YAML::Schema::Core.parse_scalar(node))\nwhen YAML::Nodes::Sequence\n  ary = [] of YAML::Any\n\n  node.each do |value|\n    ary << (new(ctx, value))\n  end\n\n  new(ary)\nwhen YAML::Nodes::Mapping\n  hash = {} of YAML::Any => YAML::Any\n\n  node.each do |key, value|\n    hash[new(ctx, key)] = new(ctx, value)\n  end\n\n  new(hash)\nwhen YAML::Nodes::Alias\n  if value = node.value\n    new(ctx, value)\n  else\n    raise(\"YAML::Nodes::Alias misses anchor value\")\n  end\nelse\n  raise(\"Unknown node: #{node.class}\")\nend"},"external_var":false},{"html_id":"new(raw:Type)-class-method","name":"new","doc":"Creates a `YAML::Any` that wraps the given `Type`.","summary":"<p>Creates a <code><a href=\"../YAML/Any.html\">YAML::Any</a></code> that wraps the given <code><a href=\"../YAML/Any/Type.html\">Type</a></code>.</p>","abstract":false,"args":[{"name":"raw","external_name":"raw","restriction":"Type"}],"args_string":"(raw : Type)","args_html":"(raw : <a href=\"../YAML/Any/Type.html\">Type</a>)","location":{"filename":"src/yaml/any.cr","line_number":66,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L66"},"def":{"name":"new","args":[{"name":"raw","external_name":"raw","restriction":"Type"}],"visibility":"Public","body":"_ = allocate\n_.initialize(raw)\nif _.responds_to?(:finalize)\n  ::GC.add_finalizer(_)\nend\n_\n"},"external_var":false},{"html_id":"new(raw:Int)-class-method","name":"new","doc":"Creates a `YAML::Any` that wraps the given `Type`.","summary":"<p>Creates a <code><a href=\"../YAML/Any.html\">YAML::Any</a></code> that wraps the given <code><a href=\"../YAML/Any/Type.html\">Type</a></code>.</p>","abstract":false,"args":[{"name":"raw","external_name":"raw","restriction":"Int"}],"args_string":"(raw : Int)","args_html":"(raw : <a href=\"../Int.html\">Int</a>)","location":{"filename":"src/yaml/any.cr","line_number":70,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L70"},"def":{"name":"new","args":[{"name":"raw","external_name":"raw","restriction":"Int"}],"visibility":"Public","body":"new(raw.to_i64)"},"external_var":false},{"html_id":"new(raw:Float)-class-method","name":"new","doc":"Creates a `YAML::Any` that wraps the given `Type`.","summary":"<p>Creates a <code><a href=\"../YAML/Any.html\">YAML::Any</a></code> that wraps the given <code><a href=\"../YAML/Any/Type.html\">Type</a></code>.</p>","abstract":false,"args":[{"name":"raw","external_name":"raw","restriction":"Float"}],"args_string":"(raw : Float)","args_html":"(raw : <a href=\"../Float.html\">Float</a>)","location":{"filename":"src/yaml/any.cr","line_number":76,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L76"},"def":{"name":"new","args":[{"name":"raw","external_name":"raw","restriction":"Float"}],"visibility":"Public","body":"new(raw.to_f64)"},"external_var":false}],"instance_methods":[{"html_id":"==(other:YAML::Any)-instance-method","name":"==","doc":"Returns `true` if both `self` and *other*'s raw object are equal.","summary":"<p>Returns <code>true</code> if both <code>self</code> and <em>other</em>'s raw object are equal.</p>","abstract":false,"args":[{"name":"other","external_name":"other","restriction":"YAML::Any"}],"args_string":"(other : YAML::Any)","args_html":"(other : <a href=\"../YAML/Any.html\">YAML::Any</a>)","location":{"filename":"src/yaml/any.cr","line_number":321,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L321"},"def":{"name":"==","args":[{"name":"other","external_name":"other","restriction":"YAML::Any"}],"visibility":"Public","body":"raw == other.raw"},"external_var":false},{"html_id":"==(other)-instance-method","name":"==","doc":"Returns `true` if the raw object is equal to *other*.","summary":"<p>Returns <code>true</code> if the raw object is equal to <em>other</em>.</p>","abstract":false,"args":[{"name":"other","external_name":"other","restriction":""}],"args_string":"(other)","args_html":"(other)","location":{"filename":"src/yaml/any.cr","line_number":326,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L326"},"def":{"name":"==","args":[{"name":"other","external_name":"other","restriction":""}],"visibility":"Public","body":"raw == other"},"external_var":false},{"html_id":"[](index_or_key):YAML::Any-instance-method","name":"[]","doc":"Assumes the underlying value is an `Array` or `Hash`\nand returns the element at the given *index_or_key*.\n\nRaises if the underlying value is not an `Array` nor a `Hash`.","summary":"<p>Assumes the underlying value is an <code><a href=\"../Array.html\">Array</a></code> or <code><a href=\"../Hash.html\">Hash</a></code> and returns the element at the given <em>index_or_key</em>.</p>","abstract":false,"args":[{"name":"index_or_key","external_name":"index_or_key","restriction":""}],"args_string":"(index_or_key) : YAML::Any","args_html":"(index_or_key) : <a href=\"../YAML/Any.html\">YAML::Any</a>","location":{"filename":"src/yaml/any.cr","line_number":99,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L99"},"def":{"name":"[]","args":[{"name":"index_or_key","external_name":"index_or_key","restriction":""}],"return_type":"YAML::Any","visibility":"Public","body":"case object = @raw\nwhen Array\n  if index_or_key.is_a?(Int)\n    object[index_or_key]\n  else\n    raise(\"Expected int key for Array#[], not #{object.class}\")\n  end\nwhen Hash\n  object[index_or_key]\nelse\n  raise(\"Expected Array or Hash, not #{object.class}\")\nend"},"external_var":false},{"html_id":"[]?(index_or_key):YAML::Any|Nil-instance-method","name":"[]?","doc":"Assumes the underlying value is an `Array` or `Hash` and returns the element\nat the given *index_or_key*, or `nil` if out of bounds or the key is missing.\n\nRaises if the underlying value is not an `Array` nor a `Hash`.","summary":"<p>Assumes the underlying value is an <code><a href=\"../Array.html\">Array</a></code> or <code><a href=\"../Hash.html\">Hash</a></code> and returns the element at the given <em>index_or_key</em>, or <code>nil</code> if out of bounds or the key is missing.</p>","abstract":false,"args":[{"name":"index_or_key","external_name":"index_or_key","restriction":""}],"args_string":"(index_or_key) : YAML::Any | Nil","args_html":"(index_or_key) : <a href=\"../YAML/Any.html\">YAML::Any</a> | <a href=\"../Nil.html\">Nil</a>","location":{"filename":"src/yaml/any.cr","line_number":118,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L118"},"def":{"name":"[]?","args":[{"name":"index_or_key","external_name":"index_or_key","restriction":""}],"return_type":"YAML::Any | ::Nil","visibility":"Public","body":"case object = @raw\nwhen Array\n  if index_or_key.is_a?(Int)\n    object[index_or_key]?\n  else\n    nil\n  end\nwhen Hash\n  object[index_or_key]?\nelse\n  raise(\"Expected Array or Hash, not #{object.class}\")\nend"},"external_var":false},{"html_id":"as_a:Array(YAML::Any)-instance-method","name":"as_a","doc":"Checks that the underlying value is `Array`, and returns its value.\nRaises otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Array.html\">Array</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":273,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L273"},"def":{"name":"as_a","return_type":"Array(YAML::Any)","visibility":"Public","body":"@raw.as(Array)"},"external_var":false},{"html_id":"as_a?:Array(YAML::Any)|Nil-instance-method","name":"as_a?","doc":"Checks that the underlying value is `Array`, and returns its value.\nReturns `nil` otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Array.html\">Array</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":279,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L279"},"def":{"name":"as_a?","return_type":"Array(YAML::Any) | ::Nil","visibility":"Public","body":"@raw.as?(Array)"},"external_var":false},{"html_id":"as_bool:Bool-instance-method","name":"as_bool","doc":"Checks that the underlying value is `Bool`, and returns its value.\nRaises otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Bool.html\">Bool</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":167,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L167"},"def":{"name":"as_bool","return_type":"Bool","visibility":"Public","body":"@raw.as(Bool)"},"external_var":false},{"html_id":"as_bool?:Bool|Nil-instance-method","name":"as_bool?","doc":"Checks that the underlying value is `Bool`, and returns its value.\nReturns `nil` otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Bool.html\">Bool</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":173,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L173"},"def":{"name":"as_bool?","return_type":"Bool | ::Nil","visibility":"Public","body":"if @raw.is_a?(Bool)\n  as_bool\nend"},"external_var":false},{"html_id":"as_bytes:Bytes-instance-method","name":"as_bytes","doc":"Checks that the underlying value is `Bytes`, and returns its value.\nRaises otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Bytes.html\">Bytes</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":297,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L297"},"def":{"name":"as_bytes","return_type":"Bytes","visibility":"Public","body":"@raw.as(Bytes)"},"external_var":false},{"html_id":"as_bytes?:Bytes|Nil-instance-method","name":"as_bytes?","doc":"Checks that the underlying value is `Bytes`, and returns its value.\nReturns `nil` otherwise.","summary":"<p>Checks that the underlying value is <code><a href=\"../Bytes.html\">Bytes</a></code>, and returns its value.</p>","abstract":false,"location":{"filename":"src/yaml/any.cr","line_number":303,"url":"https://github.com/crystal-lang/crystal/blob/af0f55415/src/yaml/any.cr#L303"},"def":{"name":"as_bytes?","return_type":"Bytes | ::Nil","visibility":"Public","body":"@raw.as?(Bytes)"},"external_var":false},{"html_id":"as_f:Float64-instance-method","name":"as_f","doc":